<script setup lang="ts">
import{computed,nextTick,onMounted,onUnmounted,ref,watch}from'vue';
import type{editor,IDisposable}from'monaco-editor';
const props=defineProps<{before:string|null;after:string;path:string}>();
const host=ref<HTMLElement>(),loading=ref(true),error=ref(''),split=ref(true),expanded=ref(false),inserted=ref(0),removed=ref(0);
let view:editor.IStandaloneDiffEditor|undefined,original:editor.ITextModel|undefined,modified:editor.ITextModel|undefined,listener:IDisposable|undefined,disposed=false;
let api:typeof import('monaco-editor/editor/editor.api')|undefined;let languageForPath=(_path:string)=>'plaintext';
const editorHeight=computed(()=>expanded.value?'72vh':'390px');
async function mount(){loading.value=true;error.value='';try{const helper=await import('../utils/monaco');const monaco=await helper.loadMonaco();if(disposed||!host.value)return;api=monaco;languageForPath=helper.codeLanguage;const codeLanguage=helper.codeLanguage;const id=crypto.randomUUID();original=monaco.editor.createModel(props.before??'',codeLanguage(props.path),monaco.Uri.from({scheme:'inmemory',authority:'ares',path:`/${id}/before/${props.path}`}));modified=monaco.editor.createModel(props.after,codeLanguage(props.path),monaco.Uri.from({scheme:'inmemory',authority:'ares',path:`/${id}/after/${props.path}`}));view=monaco.editor.createDiffEditor(host.value,{theme:'ares-review',readOnly:true,domReadOnly:true,originalEditable:false,renderSideBySide:split.value,useInlineViewWhenSpaceIsLimited:true,renderSideBySideInlineBreakpoint:640,enableSplitViewResizing:true,automaticLayout:true,fontFamily:'JetBrains Mono, monospace',fontSize:12,lineNumbers:'on',minimap:{enabled:false},scrollBeyondLastLine:false,contextmenu:false,links:false,renderValidationDecorations:'off',stickyScroll:{enabled:false},ignoreTrimWhitespace:false,diffAlgorithm:'advanced',maxComputationTime:2500,hideUnchangedRegions:{enabled:true,contextLineCount:4,minimumLineCount:12,revealLineCount:8},originalAriaLabel:`Antes: ${props.path}`,modifiedAriaLabel:`Después (propuesta): ${props.path}`});view!.setModel({original:original!,modified:modified!});listener=view!.onDidUpdateDiff(()=>{const changes=view?.getLineChanges()??[];inserted.value=changes.reduce((count,c)=>count+(c.modifiedEndLineNumber?c.modifiedEndLineNumber-c.modifiedStartLineNumber+1:0),0);removed.value=changes.reduce((count,c)=>count+(c.originalEndLineNumber?c.originalEndLineNumber-c.originalStartLineNumber+1:0),0);});}catch{if(!disposed)error.value='No se pudo cargar el comparador. Puedes consultar el parche de texto.';}finally{if(!disposed)loading.value=false;}}
watch(()=>[props.before,props.after,props.path],()=>{original?.setValue(props.before??'');modified?.setValue(props.after);if(api&&original&&modified){api.editor.setModelLanguage(original,languageForPath(props.path));api.editor.setModelLanguage(modified,languageForPath(props.path));view?.getOriginalEditor().updateOptions({ariaLabel:`Antes: ${props.path}`});view?.getModifiedEditor().updateOptions({ariaLabel:`Después (propuesta): ${props.path}`});}});
watch(split,value=>view?.updateOptions({renderSideBySide:value}));watch(expanded,async()=>{await nextTick();view?.layout();});
onMounted(mount);onUnmounted(()=>{disposed=true;listener?.dispose();view?.dispose();original?.dispose();modified?.dispose();});
</script>
<template><section class="comparative-diff" aria-label="Comparación Antes y Después" :data-ready="!loading&&!error" :data-path="path"><div class="comparison-toolbar"><strong>{{ path }}</strong><div class="comparison-actions"><button type="button" :aria-pressed="split" @click="split=!split">{{ split?'Vista unificada':'Vista en paralelo' }}</button><button type="button" :disabled="loading||!!error" @click="view?.goToDiff('previous')" aria-label="Cambio anterior">↑</button><button type="button" :disabled="loading||!!error" @click="view?.goToDiff('next')" aria-label="Cambio siguiente">↓</button><button type="button" :aria-pressed="expanded" @click="expanded=!expanded">{{ expanded?'Reducir':'Ampliar' }}</button></div></div><div class="comparison-labels"><span>ANTES <small>{{ before===null?'Archivo nuevo · vacío':'Base de comparación' }}</small></span><span>DESPUÉS <small>Contenido propuesto</small></span></div><p v-if="loading" role="status" class="comparison-notice">Cargando comparador…</p><p v-if="error" role="alert" class="comparison-notice">{{ error }}</p><div v-show="!error" ref="host" class="comparison-editor" :style="{height:editorHeight}" :aria-busy="loading"></div><div class="comparison-footer"><span class="removed">−{{ removed }} líneas</span><span class="added">+{{ inserted }} líneas</span><span>SOLO LECTURA · revisar no aplica cambios</span></div></section></template>
<style scoped>.comparative-diff{border:1px solid #2b443e;border-radius:8px;margin:18px 0;min-width:0;overflow:hidden;background:#081318}.comparison-toolbar{display:flex;align-items:center;gap:12px;justify-content:space-between;padding:12px;background:#10211f;border-bottom:1px solid #29443d;flex-wrap:wrap}.comparison-toolbar strong{font:11px var(--mono);overflow-wrap:anywhere}.comparison-actions{display:flex;gap:6px;flex-wrap:wrap}.comparison-actions button{padding:6px 9px;border:1px solid #345449;border-radius:4px;background:#0b1a17;color:#b4d8c8;font-size:10px}.comparison-labels{display:grid;grid-template-columns:1fr 1fr;gap:16px;padding:10px 15px;background:#09191a;font:10px var(--mono);letter-spacing:.7px;border-bottom:1px solid #203731}.comparison-labels>span:first-child{color:#e5a0ab}.comparison-labels>span:last-child{color:#8fe4b9}.comparison-labels small{font-size:9px;letter-spacing:0;color:#819d99;display:block;margin-top:5px}.comparison-editor{width:100%;min-width:0}.comparison-footer{display:flex;flex-wrap:wrap;gap:14px;padding:10px 14px;border-top:1px solid #29443d;font:9px var(--mono);color:#718e89}.comparison-footer>span:last-child{margin-left:auto}.removed{color:#e7a3af}.added{color:#88e5b1}.comparison-notice{padding:15px;color:#9bb7ae;font-size:12px}@media(max-width:700px){.comparison-toolbar{padding:10px}.comparison-labels{padding:9px}.comparison-footer>span:last-child{margin-left:0;font-size:8px}}
</style>
